/**
 * The subscription, when one exists, is the authority on the workspace plan.
 * `organizations.plan` is a denormalised copy that can lag a plan change, or
 * disagree on rows written before the copy was kept in step. Callers that
 * already hold an `Organization` — quotas, flags, the switcher, the header —
 * therefore see the subscription plan without a second lookup. A workspace
 * with no subscription row keeps the plan stored on itself.
 */
async function withEffectivePlan(org: Organization): Promise<Organization> {
  const subscription = await findSubscription(org.id);
  if (!subscription || subscription.plan === org.plan) return org;
  return { ...org, plan: subscription.plan };
}

