/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

input.new_string:
/**
 * Fallback plan for an org whose subscription row cannot be read — unit tests
 * record one with `setOrgPlan`, and a workspace with no subscription keeps
 * whatever was recorded here. A live subscription always wins over this map,
 * so a plan change takes effect on the next call without a process restart.
 */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

/**
 * Subscription plan, then the plan stored on the workspace, then a plan
 * recorded with `setOrgPlan`, then free. One org's row never supplies
 * another org's ceiling: the lookup is keyed by `orgId` alone.
 */
async function resolveLimiterPlan(orgId: OrgId): Promise<PlanId> {
  const recorded = planByOrg.get(orgId);
  // The token-bucket unit tests have no database. Opening the default file
  // here would create one just to discover the tables are missing.
  if (process.env.NODE_ENV === "test" && !process.env.TASKFLOW_DB_PATH) {
    return recorded ?? "free";
  }

  try {
    const { findSubscription } = await import(
      "@/server/repositories/subscription-repository"
    );
    const subscription = await findSubscription(orgId);
    if (subscription) return subscription.plan;

    const { findOrgById } = await import(
      "@/server/repositories/organization-repository"
    );
    const org = await findOrgById(orgId);
    if (org) return org.plan;
  } catch {
    // No migrated database. The recorded plan, when there is one, still applies.
  }

  return recorded ?? "free";
}

